import React from 'react';
import { render, screen, fireEvent } from '@testing-library/react';
import TextArea from './TextArea';

describe('TextArea', () => {
  test('should render input with label', () => {
    render(<TextArea label="Name" data-testid="textarea-test" />);
    expect(screen.getByText('Name')).toBeInTheDocument();
    const input = screen.getByTestId('textarea-test');
    fireEvent.change(input, { target: { value: 'abc' } });
    expect(input.value).toBe('abc');
  });

  test('should render when controlled', () => {
    let mockValue = '';
    const mockOnChange = jest.fn();
    mockOnChange.mockImplementation((event) => {
      mockValue = event.target.value;
    });

    const { rerender } = render(
      <TextArea value={mockValue} onChange={mockOnChange} data-testid="textarea-test" />
    );
    const input = screen.getByTestId('textarea-test');
    fireEvent.change(input, { target: { value: 'abc' } });
    expect(mockOnChange).toHaveBeenCalledTimes(1);
    rerender(<TextArea value={mockValue} onChange={mockOnChange} data-testid="textarea-test" />);
    expect(input.value).toBe('abc');
  });

  test('should change the value when onChange is passed as prop', () => {
    const mockOnChange = jest.fn();
    render(<TextArea onChange={mockOnChange} data-testid="textarea-test" />);
    const input = screen.getByTestId('textarea-test');
    fireEvent.change(input, { target: { value: 'abc' } });
    expect(mockOnChange).toHaveBeenCalledTimes(1);
    expect(input.value).toBe('abc');
  });

  test('should render with default value', () => {
    render(<TextArea data-testid="textarea-test" defaultValue="abc123" />);
    const input = screen.getByTestId('textarea-test');
    expect(input.value).toBe('abc123');
  });

  test('should render with error', () => {
    render(<TextArea data-testid="textarea-test" hasError />);
    expect(screen.getByTestId('textarea-test')).toBeInTheDocument();
  });

  test('should render disabled', () => {
    render(<TextArea data-testid="textarea-test" disabled />);
    expect(screen.getByTestId('textarea-test')).toBeInTheDocument();
  });
});
